Lemma qfiQR_conc fx R M (V : nat -> Z) :
  0 <= (V 2%nat) < 2 ^ 64 -> 0 <= (V 40%nat) < 2 ^ 64 -> 0 <= (V 50%nat) < 2 ^ 64 ->
  getr R (reg 2) = Z_to_bv 64 (V 2%nat) -> getr R (reg 22) = Z_to_bv 64 ((V 50%nat) + (V 40%nat)) -> getr R (reg 25) = Z_to_bv 64 ((V 50%nat) + 32) -> getr R (reg 26) = Z_to_bv 64 ((V 50%nat) + (V 40%nat)) ->
  7036928 <= (V 50%nat) <= 140737488354816 -> aligned (V 50%nat) 32 -> (2147446784 + 17592186048512 <= (V 50%nat) \/ (V 50%nat) + 512 <= 2147446784) -> 33 <= (V 40%nat) <= 51 ->
  exists fx' R' M', mem_grows M M'
    /\ (forall a : word, M' a = M a)
    /\ (forall i : Z, 0 <= i < 2 ^ 64 -> M' (Z_to_bv 64 i) = M (Z_to_bv 64 i))
    /\ (msteps RSEGS (st fx R 0xba49c M) (st fx' R' 0xba480 M')
