Lemma qcxD_conc fx R M (V : nat -> Z) :
  0 <= (V 2%nat) < 2 ^ 64 -> 0 <= (V 33%nat) < 2 ^ 64 -> 0 <= (V 39%nat) < 2 ^ 64 -> 0 <= (V 41%nat) < 2 ^ 64 ->
  getr R (reg 2) = Z_to_bv 64 (V 2%nat) -> getr R (reg 10) = Z_to_bv 64 (V 33%nat) -> getr R (reg 11) = Z_to_bv 64 (V 39%nat) ->
  L5.img_clear M 65536 1409024 -> L5.u64_at RSEGS M 1440376 2147450880 -> L5.u32_at RSEGS M 1440384 1 -> 140735332487184 <= (V 2%nat) <= 140737488355328 ->
  aligned (V 2%nat) 16 -> L5.writable RSEGS M ((V 2%nat) - 16) 16 -> 7036928 <= (V 39%nat) <= 140737488355296 -> aligned (V 39%nat) 8 ->
  (2147446784 + 17592186048512 <= (V 39%nat) \/ (V 39%nat) + 32 <= 2147446784) -> L5KA.zeros_at M (((V 39%nat) / 8) + 2147450880) 1 -> L5.u8_at RSEGS M (V 39%nat) (V 41%nat) -> 0 <= (V 41%nat) <= 255 ->
  Z.testbit (V 41%nat) 0 = true -> (((V 2%nat) - 16) + 16 <= (V 39%nat) \/ (V 39%nat) + 32 <= ((V 2%nat) - 16)) ->
  exists fx' R' M', mem_grows M M'
    /\ (forall a : word, ~ (((V 2%nat) - 8) <= bv_unsigned a < ((V 2%nat) - 8) + 8) -> M' a = M a)
    /\ (forall i : Z, 0 <= i < 2 ^ 64 -> ~ (((V 2%nat) - 8) <= i < ((V 2%nat) - 8) + 8) -> M' (Z_to_bv 64 i) = M (Z_to_bv 64 i))
    /\ (msteps RSEGS (st fx R 0xcc9d8 M) (st fx' R' 0xcb80c M')
        /\ (forall x, In x KS_qcxD -> getr R' (reg x) = getr R (reg x))
        /\ getr R' (reg 13) = Z_to_bv 64 (((V 39%nat) / 8) + 2147450880)
        /\ getr R' (reg 14) = Z_to_bv 64 2147450880
